package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.service.articles.EntityDedupService;
import java.util.*;
import org.junit.jupiter.api.*;

/** The shared pure automatic identity is checked against an actual native business receipt. */
class EntityAutomaticIdentityTest {
    EntityHeatBusinessProducerTest h;
    GenerationJdbcStoreTest fixture(){return new GenerationJdbcStoreTest();}
    @BeforeEach void setup(){h=new EntityHeatBusinessProducerTest(){@Override GenerationJdbcStoreTest fixture(){return EntityAutomaticIdentityTest.this.fixture();}};h.setup();}
    @Test void PureIdentityIsExactlyTheActualBusinessWriterRequestHashAndReplayDoesNotChangeIt(){h.item("fictional-one","fictional-source","fictional-key");var command=h.command("fictional-one","new",null);String hash=EntityDedupService.automaticFingerprint(command);var action=h.action("fictional-create","fictional-entity");var original=h.business.applyAutomatic(command,action);assertEquals(hash,h.receipts().getFirst().get("request_hash").asText());h.f.jdbc.execute("DROP TABLE analyzed_entities");assertEquals(hash,EntityDedupService.automaticFingerprint(command));assertEquals(original,h.business.applyAutomatic(command,action));assertEquals(1,h.receipts().size());}
    @Test void EveryAutomaticBusinessFieldAndCandidateOrderAffectTheSameIdentity(){var base=new EntityDedupService.Automatic("fictional-one",1,"existing","news_tech","fictional-identity","fictional-entity",List.of("fictional-entity","fictional-second"),"Fictional title","Fictional summary","Fictional reason");String original=EntityDedupService.automaticFingerprint(base);var variants=List.of(new EntityDedupService.Automatic("fictional-two",1,base.decision(),base.category(),base.identityKey(),base.proposedEntityId(),base.candidateEntityIds(),base.title(),base.summary(),base.reason()),new EntityDedupService.Automatic(base.itemId(),2,base.decision(),base.category(),base.identityKey(),base.proposedEntityId(),base.candidateEntityIds(),base.title(),base.summary(),base.reason()),new EntityDedupService.Automatic(base.itemId(),1,"new",base.category(),base.identityKey(),base.proposedEntityId(),base.candidateEntityIds(),base.title(),base.summary(),base.reason()),new EntityDedupService.Automatic(base.itemId(),1,base.decision(),"agent",base.identityKey(),base.proposedEntityId(),base.candidateEntityIds(),base.title(),base.summary(),base.reason()),new EntityDedupService.Automatic(base.itemId(),1,base.decision(),base.category(),"fictional-other",base.proposedEntityId(),base.candidateEntityIds(),base.title(),base.summary(),base.reason()),new EntityDedupService.Automatic(base.itemId(),1,base.decision(),base.category(),base.identityKey(),"fictional-second",base.candidateEntityIds(),base.title(),base.summary(),base.reason()),new EntityDedupService.Automatic(base.itemId(),1,base.decision(),base.category(),base.identityKey(),base.proposedEntityId(),List.of("fictional-second","fictional-entity"),base.title(),base.summary(),base.reason()),new EntityDedupService.Automatic(base.itemId(),1,base.decision(),base.category(),base.identityKey(),base.proposedEntityId(),base.candidateEntityIds(),"Fictional other title",base.summary(),base.reason()),new EntityDedupService.Automatic(base.itemId(),1,base.decision(),base.category(),base.identityKey(),base.proposedEntityId(),base.candidateEntityIds(),base.title(),null,base.reason()),new EntityDedupService.Automatic(base.itemId(),1,base.decision(),base.category(),base.identityKey(),base.proposedEntityId(),base.candidateEntityIds(),base.title(),base.summary(),"Fictional other reason"));var hashes=new HashSet<String>();hashes.add(original);for(var value:variants)assertTrue(hashes.add(EntityDedupService.automaticFingerprint(value)));assertEquals(original,EntityDedupService.automaticFingerprint(base));}
    @Test void MalformedAutomaticValuesAreRejectedBeforeAnyNativeIo(){assertThrows(RuntimeException.class,()->EntityDedupService.automaticFingerprint(null));assertThrows(RuntimeException.class,()->EntityDedupService.automaticFingerprint(new EntityDedupService.Automatic("fictional-one",-1,"new","news_tech","fictional-identity",null,List.of(),"Fictional title",null,"Fictional reason")));var command=h.command("fictional-one","new",null);h.f.jdbc.execute("DROP TABLE source_run_items");h.f.jdbc.execute("DROP TABLE source_runs");h.f.jdbc.execute("DROP TABLE analyzed_entities");assertNotNull(EntityDedupService.automaticFingerprint(command));assertTrue(h.receipts().isEmpty());}
}
